   513→/* ===================================================
   514→   QUICK MODE — Web Speech API
   515→   No WebSocket. No backend. Browser-only.
   516→   =================================================== */
   517→
   518→const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
   519→
   520→function getRecognitionLang() {
   521→    return localStorage.getItem('recognitionLang') || navigator.language || 'en-US';
   522→}
   523→
   524→function initRecognition() {
   525→    if (!SpeechRecognition) return;
   526→
   527→    recognition = new SpeechRecognition();
   528→    recognition.continuous      = true;
   529→    recognition.interimResults  = true;
   530→    recognition.lang            = getRecognitionLang();
   531→    recognition.maxAlternatives = 1;
   532→
   533→    recognition.onstart = () => {
   534→        isListening      = true;
   535→        quickFinalTranscript = '';
   536→        showLiveTranscript('', 'quick');
   537→        quickBtn.classList.add('recording');
   538→        quickRing.classList.add('recording');
   539→        quickBtn.setAttribute('aria-pressed', 'true');
   540→        brainstormBtn.disabled = true;
   541→        replayButton.disabled  = true;
   542→        micHint.textContent = 'Listening… tap Quick to stop';
   543→        micHint.classList.add('active');
   544→        micHint.classList.remove('brainstorm-active', 'processing');
   545→    };
   546→
   547→    recognition.onresult = (event) => {
   548→        let interim = '';
   549→        for (let i = event.resultIndex; i < event.results.length; i++) {
   550→            const result = event.results[i];
   551→            if (result.isFinal) {
   552→                quickFinalTranscript += result[0].transcript + ' ';
   553→            } else {
   554→                interim += result[0].transcript;
   555→            }
   556→        }
   557→        const displayText = (quickFinalTranscript + interim).trim();
   558→        updateLiveText(displayText);
   559→        resetSilenceTimer();
   560→    };
   561→
   562→    recognition.onerror = (event) => {
   563→        if (event.error !== 'no-speech') {
   564→            console.warn('Speech recognition error:', event.error);
   565→        }
   566→        stopQuickMode();
   567→    };
   568→
   569→    recognition.onend = () => {
   570→        // If we didn't stop manually, recognition auto-stopped
   571→        if (isListening) {
   572→            finishQuickRecording();
   573→        }
   574→    };
   575→}
   576→
   577→function resetSilenceTimer() {
   578→    clearTimeout(silenceTimer);
   579→    silenceTimer = setTimeout(() => {
   580→        if (isListening) stopQuickMode();
   581→    }, SILENCE_DELAY);
   582→}
   583→
   584→function startQuickMode() {
   585→    if (isListening || isBrainstormRecording || isBrainstormProcessing || isReplaying) return;
   586→    if (!recognition) {
   587→        alert('Speech recognition is not available in this browser.');
   588→        return;
   589→    }
   590→    hideTranscriptBar();
   591→    // Stop any active local playback
   592→    if (isPlayingBack) stopLocalPlayback();
   593→    // Stop wake word listener if running (can't run both concurrently)
   594→    if (wakeWordListening) stopWakeWordListening();
   595→    try {
   596→        recognition.start();
   597→    } catch (e) {
   598→        console.warn('Could not start recognition:', e);
   599→        initRecognition();
   600→        try { recognition.start(); } catch (_) {}
   601→    }
   602→    resetSilenceTimer();
   603→}
   604→
   605→function stopQuickMode() {
   606→    clearTimeout(silenceTimer);
