   653→function matchesWakeWord(text) {
   654→    const t = text.toLowerCase().trim();
   655→    // Fuzzy patterns: "hey chill", "hey chil", "a chill", "hay chill", etc.
   656→    return /\b(hey|hay|a)\s+chil{1,2}\b/.test(t);
   657→}
