   659→function initWakeRecognition() {
   660→    if (!SpeechRecognition) return;
   661→
   662→    wakeRecognition = new SpeechRecognition();
   663→    wakeRecognition.continuous      = true;
   664→    wakeRecognition.interimResults  = true;
   665→    wakeRecognition.lang            = getRecognitionLang();
   666→    wakeRecognition.maxAlternatives = 3;
   667→
   668→    wakeRecognition.onresult = (event) => {
   669→        for (let i = event.resultIndex; i < event.results.length; i++) {
   670→            const result = event.results[i];
   671→            for (let j = 0; j < result.length; j++) {
   672→                if (matchesWakeWord(result[j].transcript)) {
   673→                    handleWakeWordDetected();
   674→                    return;
   675→                }
   676→            }
   677→        }
   678→    };
   679→
   680→    wakeRecognition.onerror = (event) => {
   681→        if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
   682→            console.warn('Wake word mic denied:', event.error);
   683→            wakeWordListening = false;
   684→            updateWakeDot();
   685→            return;
   686→        }
   687→        // Transient error — will be restarted by onend handler
   688→    };
   689→
   690→    wakeRecognition.onend = () => {
   691→        wakeWordListening = false;
   692→        updateWakeDot();
   693→        // Auto-restart when not in an active mode
   694→        if (handsFreeEnabled && !isListening && !isBrainstormRecording && !isBrainstormProcessing) {
   695→            setTimeout(startWakeWordListening, 300);
   696→        }
   697→    };
