   755→function getWebSocketUrl() {
   756→    const backendUrl = localStorage.getItem('brainwaveBackendUrl') || '';
   757→    if (backendUrl) {
   758→        try {
   759→            const url    = new URL(backendUrl);
   760→            const wsProto = url.protocol === 'https:' ? 'wss:' : 'ws:';
   761→            return `${wsProto}//${url.host}/api/v1/ws`;
   762→        } catch (_) { /* fall through to default */ }
   763→    }
