   804→
   805→    ws.onmessage = (event) => {
   806→        const data = JSON.parse(event.data);
   807→        switch (data.type) {
   808→            case 'status':
   809→                updateConnectionStatus(data.status);
   810→                if (data.status === 'idle') {
   811→                    stopTimer();
   812→                    if (_awaitingBrainstormResult) {
   813→                        _awaitingBrainstormResult = false;
   814→                        isBrainstormProcessing    = false;
   815→                        quickBtn.disabled         = false;
   816→                        brainstormBtn.disabled    = false;
   817→                        micHint.textContent       = '';
   818→                        micHint.classList.remove('active', 'brainstorm-active', 'processing');
   819→                        hideLiveTranscript();
   820→                        updateReplayButtonState();
   821→                        const finalText = brainstormTranscript.trim();
   822→                        brainstormTranscript = '';
   823→                        if (finalText) {
   824→                            showCardStack(finalText, lastRecordingDurationMs);
   825→                        }
   826→                        // Resume hands-free after brainstorm completes
   827→                        if (handsFreeEnabled) {
   828→                            setTimeout(startWakeWordListening, 400);
   829→                        }
   830→                    }
   831→                }
   832→                break;
   833→
   834→            case 'text':
   835→                if (data.isNewResponse) {
   836→                    brainstormTranscript = data.content;
   837→                } else {
   838→                    brainstormTranscript += data.content;
   839→                }
   840→                if (isBrainstormProcessing) {
   841→                    updateLiveText(brainstormTranscript);
   842→                }
   843→                break;
   844→
   845→            case 'error':
   846→                alert(data.content);
   847→                updateConnectionStatus('idle');
   848→                _awaitingBrainstormResult = false;
   849→                isBrainstormProcessing    = false;
   850→                quickBtn.disabled         = false;
   851→                brainstormBtn.disabled    = false;
   852→                micHint.textContent       = '';
   853→                micHint.classList.remove('active', 'brainstorm-active', 'processing');
   854→                hideLiveTranscript();
   855→                brainstormTranscript = '';
   856→                updateReplayButtonState();
   857→                if (handsFreeEnabled) {
   858→                    setTimeout(startWakeWordListening, 400);
   859→                }
   860→                break;
   861→        }
   862→    };
   863→
   864→    ws.onclose = () => {
   865→        wsConnected            = false;
   866→        isBrainstormRecording  = false;
   867→        isStopping             = false;
   868→        updateConnectionStatus('disconnected');
   869→        brainstormBtn.classList.remove('recording');
   870→        brainstormRing.classList.remove('recording');
   871→        brainstormBtn.setAttribute('aria-pressed', 'false');
