   877→/* ===== Audio processing ===== */
   878→function createAudioProcessor() {
   879→    processor = audioContext.createScriptProcessor(4096, 1, 1);
   880→    processor.onaudioprocess = async (e) => {
   881→        if (!isBrainstormRecording && !isStopping) return;
   882→
   883→        const inputData = e.inputBuffer.getChannelData(0);
   884→        const pcmData   = new Int16Array(inputData.length);
   885→        for (let i = 0; i < inputData.length; i++) {
   886→            pcmData[i] = Math.max(-32768, Math.min(32767, Math.floor(inputData[i] * 32767)));
   887→        }
   888→
   889→        const combined = new Int16Array(audioBuffer.length + pcmData.length);
   890→        combined.set(audioBuffer);
   891→        combined.set(pcmData, audioBuffer.length);
   892→        audioBuffer = combined;
   893→
   894→        if (audioBuffer.length >= 24000) {
   895→            const sendBuffer = audioBuffer.slice(0, 24000);
   896→            audioBuffer      = audioBuffer.slice(24000);
   897→
   898→            if (ws.readyState === WebSocket.OPEN) {
   899→                ws.send(sendBuffer.buffer);
   900→
   901→                if (storageAvailable && currentSessionId && sessionStartTime) {
   902→                    const deltaMs = performance.now() - sessionStartTime;
   903→                    await appendChunk(currentSessionId, {
   904→                        seq: chunkSeq++, deltaMs,
   905→                        kind: 'audio', payload: sendBuffer.buffer, byteLength: sendBuffer.byteLength,
   906→                    });
   907→                }
   908→            }
   909→        }
   910→    };
   911→    return processor;
   912→}
   913→
   914→async function initAudio(audioStream) {
   915→    if (audioContext && audioContext.state !== 'closed') {
   916→        try { await audioContext.close(); } catch (_) {}
   917→    }
   918→    audioContext = new (window.AudioContext || window.webkitAudioContext)();
   919→    source       = audioContext.createMediaStreamSource(audioStream);
   920→    processor    = createAudioProcessor();
   921→    source.connect(processor);
   922→    processor.connect(audioContext.destination);
   923→    if (audioContext.state === 'suspended') await audioContext.resume();
   924→}
   925→
   926→function cleanupAudioResources() {
   927→    if (stream) {
   928→        stream.getTracks().forEach(t => t.stop());
   929→        stream = null;
   930→    }
   931→    if (audioContext && audioContext.state !== 'closed') {
   932→        audioContext.close().catch(() => {});
   933→        audioContext = null;
   934→    }
   935→    source            = null;
   936→    processor         = null;
   937→    streamInitialized = false;
   938→}
