   940→async function startBrainstormRecording() {
   941→    if (isBrainstormRecording || isListening || isBrainstormProcessing || isReplaying) return;
   942→
   943→    if (!ws || ws.readyState !== WebSocket.OPEN) {
   944→        alert('WebSocket is not connected. Please wait or check the backend URL in Settings.');
   945→        return;
   946→    }
   947→
   948→    // Pause wake word listening while brainstorm is active
   949→    if (wakeWordListening) stopWakeWordListening();
   950→
   951→    // Stop any active local playback
   952→    if (isPlayingBack) stopLocalPlayback();
   953→
   954→    try {
   955→        brainstormTranscript = '';
   956→        hideTranscriptBar();
   957→        hideCardStackInstant();
   958→
   959→        // Re-use existing stream if still alive, else reinit
   960→        let streamActive = false;
   961→        try {
   962→            streamActive = streamInitialized && stream && stream.active &&
   963→                           stream.getTracks().every(t => t.readyState === 'live');
   964→        } catch (_) { streamActive = false; }
   965→
   966→        if (!streamActive) {
   967→            cleanupAudioResources();
   968→            stream = await navigator.mediaDevices.getUserMedia({
   969→                audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true, autoGainControl: true },
   970→            });
   971→            streamInitialized = true;
   972→        }
   973→
   974→        if (!audioContext || audioContext.state === 'closed') {
   975→            await initAudio(stream);
   976→        } else if (audioContext.state === 'suspended') {
   977→            await audioContext.resume();
   978→        }
   979→
   980→        isBrainstormRecording = true;
   981→        if (storageAvailable) await createSession();
   982→
   983→        const selectedModel = modelSelect ? modelSelect.value : 'gpt-realtime-mini-2025-12-15';
   984→        ws.send(JSON.stringify({ type: 'start_recording', model: selectedModel }));
   985→
   986→        startTimer();
   987→        brainstormBtn.classList.add('recording');
   988→        brainstormRing.classList.add('recording');
   989→        brainstormBtn.setAttribute('aria-pressed', 'true');
   990→        quickBtn.disabled    = true;
   991→        replayButton.disabled = true;
   992→        micHint.textContent  = 'Recording… tap Brainstorm to stop';
   993→        micHint.classList.add('active', 'brainstorm-active');
   994→        micHint.classList.remove('processing');
   995→        showLiveTranscript('', 'brainstorm');
   996→
   997→    } catch (error) {
   998→        console.error('Error starting Brainstorm:', error);
   999→        isBrainstormRecording = false;
  1000→        alert('Error accessing microphone: ' + error.message);
  1001→    }
  1002→}
