  1004→async function stopBrainstormRecording() {
  1005→    if (!isBrainstormRecording) return;
  1006→
  1007→    isStopping               = true;
  1008→    isBrainstormRecording    = false;
  1009→    const durationMs         = sessionStartTime ? performance.now() - sessionStartTime : 0;
  1010→    lastRecordingDurationMs  = durationMs;
  1011→
  1012→    stopTimer();
  1013→    brainstormBtn.classList.remove('recording');
  1014→    brainstormRing.classList.remove('recording');
  1015→    brainstormBtn.setAttribute('aria-pressed', 'false');
  1016→    brainstormBtn.disabled = true; // keep disabled until WS idle
  1017→
  1018→    micHint.textContent = 'Processing…';
  1019→    micHint.classList.remove('brainstorm-active');
  1020→    micHint.classList.add('processing');
  1021→
  1022→    // Allow any in-flight onaudioprocess callbacks to complete
  1023→    await new Promise(resolve => setTimeout(resolve, 100));
  1024→
  1025→    // Flush remaining audio buffer
  1026→    if (audioBuffer.length > 0 && ws.readyState === WebSocket.OPEN) {
  1027→        const sendBuffer = audioBuffer.slice();
  1028→        ws.send(sendBuffer.buffer);
  1029→        if (storageAvailable && currentSessionId && sessionStartTime) {
  1030→            const deltaMs = performance.now() - sessionStartTime;
  1031→            await appendChunk(currentSessionId, {
  1032→                seq: chunkSeq++, deltaMs,
  1033→                kind: 'audio', payload: sendBuffer.buffer, byteLength: sendBuffer.byteLength,
  1034→            });
  1035→        }
  1036→        audioBuffer = new Int16Array(0);
  1037→    }
  1038→
  1039→    isStopping = false;
  1040→
  1041→    // Small delay to ensure all audio sent before stop signal
  1042→    await new Promise(resolve => setTimeout(resolve, 500));
  1043→    ws.send(JSON.stringify({ type: 'stop_recording' }));
  1044→
  1045→    if (storageAvailable && currentSessionId) {
  1046→        await completeSession(currentSessionId, durationMs);
  1047→        currentSessionId  = null;
  1048→        sessionStartTime  = null;
  1049→        chunkSeq          = 0;
  1050→        invalidateReplayBuffer();
  1051→    }
  1052→
  1053→    // Switch to processing state — WS idle handler will finish the flow
  1054→    isBrainstormProcessing    = true;
  1055→    _awaitingBrainstormResult = true;
  1056→    liveText.textContent      = 'Processing…';
  1057→    liveText.classList.remove('has-text');
  1058→}
