  1069→/* ===================================================
  1070→   REPLAY — local audio playback of stored recording
  1071→   =================================================== */
  1072→
  1073→/** Assemble PCM16 chunks from IndexedDB into a Web Audio AudioBuffer. */
  1074→async function buildReplayAudioBuffer() {
  1075→    const session = await getLatestCompletedSession();
  1076→    if (!session) return null;
  1077→    const chunks      = await getSessionChunks(session.id);
  1078→    const audioChunks = chunks.filter(c => c.kind === 'audio' && c.payload);
  1079→    if (audioChunks.length === 0) return null;
  1080→
  1081→    const SAMPLE_RATE = session.sampleRate || 24000;
  1082→    let totalSamples  = 0;
  1083→    for (const chunk of audioChunks) totalSamples += new Int16Array(chunk.payload).length;
  1084→
  1085→    // AudioBuffer constructor (Chrome 55+, FF 53+, Safari 14.1+)
  1086→    const audioBuf    = new AudioBuffer({ numberOfChannels: 1, length: totalSamples, sampleRate: SAMPLE_RATE });
  1087→    const channelData = audioBuf.getChannelData(0);
  1088→    let offset = 0;
  1089→    for (const chunk of audioChunks) {
  1090→        const pcm = new Int16Array(chunk.payload);
  1091→        for (let i = 0; i < pcm.length; i++) channelData[offset++] = pcm[i] / 32768;
  1092→    }
  1093→    return audioBuf;
  1094→}
  1095→
  1096→function _replaySetPlayIcon(playing) {
  1097→    const playIcon  = replayButton.querySelector('.replay-icon-play');
  1098→    const pauseIcon = replayButton.querySelector('.replay-icon-pause');
  1099→    if (playIcon)  playIcon.hidden  = playing;
  1100→    if (pauseIcon) pauseIcon.hidden = !playing;
  1101→}
  1102→
  1103→function _replayTickProgress() {
  1104→    if (!isPlayingBack || !replayAudioCtx) return;
  1105→    const elapsed = (replayAudioCtx.currentTime - replayStartedAt) + replayPauseOffset;
  1106→    const pct = replayDuration > 0 ? Math.min(elapsed / replayDuration, 1) : 0;
  1107→    if (replayProgressFill) replayProgressFill.style.width = (pct * 100).toFixed(2) + '%';
  1108→    if (pct < 1) replayRAF = requestAnimationFrame(_replayTickProgress);
  1109→}
  1110→
  1111→async function _ensureReplayAudioCtx() {
  1112→    if (!replayAudioCtx || replayAudioCtx.state === 'closed') {
  1113→        replayAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
  1114→    }
  1115→    if (replayAudioCtx.state === 'suspended') await replayAudioCtx.resume();
  1116→}
  1117→
  1118→function _replayOnEnded() {
  1119→    isPlayingBack     = false;
  1120→    isReplaying       = false;
  1121→    replayAudioSource = null;
  1122→    replayPauseOffset = 0;
  1123→    replayStartedAt   = 0;
  1124→    cancelAnimationFrame(replayRAF);
  1125→    if (replayProgressFill) replayProgressFill.style.width = '0%';
  1126→    _replaySetPlayIcon(false);
  1127→    stopButton.hidden = true;
  1128→    replayButton.classList.remove('replay-playing');
  1129→    if (replayProgressWrap) replayProgressWrap.hidden = true;
  1130→    updateReplayButtonState();
  1131→}
  1132→
  1133→async function toggleLocalPlayback() {
  1134→    if (isBrainstormRecording || isListening || isBrainstormProcessing) return;
  1135→
  1136→    if (isPlayingBack) {
  1137→        // Pause: record elapsed time and stop source
  1138→        replayPauseOffset += replayAudioCtx.currentTime - replayStartedAt;
  1139→        if (replayAudioSource) {
  1140→            replayAudioSource.onended = null;
  1141→            replayAudioSource.stop();
  1142→            replayAudioSource = null;
  1143→        }
  1144→        cancelAnimationFrame(replayRAF);
  1145→        isPlayingBack = false;
  1146→        isReplaying   = false;
  1147→        _replaySetPlayIcon(false);
  1148→        replayButton.classList.remove('replay-playing');
  1149→        replayButton.title = 'Resume playback';
  1150→        return;
  1151→    }
  1152→
  1153→    // Load buffer on first play (or after stop cleared it)
  1154→    if (!replayAudioBuf) {
  1155→        replayButton.disabled = true;
  1156→        replayButton.title    = 'Loading…';
  1157→        try {
  1158→            replayAudioBuf = await buildReplayAudioBuffer();
  1159→        } catch (e) {
  1160→            console.error('Failed to build audio buffer:', e);
  1161→            replayButton.disabled = false;
  1162→            updateReplayButtonState();
  1163→            return;
  1164→        }
  1165→        if (!replayAudioBuf) {
  1166→            updateReplayButtonState();
  1167→            return;
  1168→        }
  1169→        replayDuration = replayAudioBuf.duration;
  1170→    }
  1171→
  1172→    // Restart from beginning if we've reached the end
  1173→    if (replayPauseOffset >= replayDuration) {
  1174→        replayPauseOffset = 0;
  1175→        if (replayProgressFill) replayProgressFill.style.width = '0%';
  1176→    }
  1177→
  1178→    try {
  1179→        await _ensureReplayAudioCtx();
  1180→        const src = replayAudioCtx.createBufferSource();
  1181→        src.buffer = replayAudioBuf;
  1182→        src.connect(replayAudioCtx.destination);
  1183→        src.onended = _replayOnEnded;
  1184→
  1185→        replayAudioSource = src;
  1186→        replayStartedAt   = replayAudioCtx.currentTime;
  1187→        isPlayingBack     = true;
  1188→        isReplaying       = true;
  1189→
  1190→        src.start(0, replayPauseOffset);
  1191→
  1192→        _replaySetPlayIcon(true);
  1193→        replayButton.classList.add('replay-playing');
  1194→        replayButton.disabled = false;
  1195→        replayButton.title    = 'Pause playback';
  1196→        stopButton.hidden     = false;
  1197→        if (replayProgressWrap) replayProgressWrap.hidden = false;
  1198→        replayRAF = requestAnimationFrame(_replayTickProgress);
  1199→    } catch (e) {
  1200→        console.error('Playback error:', e);
  1201→        isPlayingBack = false;
  1202→        isReplaying   = false;
  1203→        updateReplayButtonState();
  1204→    }
  1205→}
  1206→
  1207→function stopLocalPlayback() {
  1208→    if (replayAudioSource) {
  1209→        replayAudioSource.onended = null;
  1210→        try { replayAudioSource.stop(); } catch (_) {}
  1211→        replayAudioSource = null;
  1212→    }
  1213→    cancelAnimationFrame(replayRAF);
  1214→    isPlayingBack     = false;
  1215→    isReplaying       = false;
  1216→    replayPauseOffset = 0;  // reset to start; buffer stays cached for fast re-play
  1217→    if (replayProgressFill) replayProgressFill.style.width = '0%';
  1218→    _replaySetPlayIcon(false);
  1219→    if (replayProgressWrap) replayProgressWrap.hidden = true;
  1220→    stopButton.hidden = true;
  1221→    replayButton.classList.remove('replay-playing');
  1222→    replayButton.title = 'Play last recording';
  1223→    updateReplayButtonState();
  1224→}
  1225→
  1226→/** Called when a new recording is completed — invalidate the cached buffer. */
  1227→function invalidateReplayBuffer() {
  1228→    replayAudioBuf = null;
  1229→    if (!isPlayingBack) {
  1230→        replayPauseOffset = 0;
  1231→        if (replayProgressFill) replayProgressFill.style.width = '0%';
  1232→    }
  1233→}
  1234→
  1235→replayButton.onclick = toggleLocalPlayback;
  1236→stopButton.onclick   = stopLocalPlayback;
  1237→
  1238→function updateReplayButtonState() {
  1239→    if (!replayButton) return;
  1240→
  1241→    if (!storageAvailable) {
  1242→        replayButton.disabled = true;
  1243→        replayButton.title    = 'Local storage not available';
  1244→        return;
  1245→    }
  1246→    if (isBrainstormRecording || isListening || isBrainstormProcessing) {
  1247→        replayButton.disabled = true;
  1248→        stopButton.hidden     = true;
  1249→        return;
  1250→    }
  1251→    if (isPlayingBack) {
  1252→        replayButton.disabled = false;
  1253→        replayButton.title    = 'Pause playback';
  1254→        return;
  1255→    }
  1256→
  1257→    getLatestCompletedSession().then(session => {
  1258→        if (!isPlayingBack) {
  1259→            replayButton.disabled = !session;
  1260→            if (session) {
  1261→                replayButton.title         = replayPauseOffset > 0 ? 'Resume playback' : 'Play last recording';
  1262→                replayButton.dataset.state = 'available';
  1263→            } else {
  1264→                replayButton.title         = 'No recording to replay';
  1265→                replayButton.dataset.state = '';
  1266→            }
  1267→        }
  1268→    });
  1269→}
  1270→
  1271→/* ===================================================
  1272→   INDEXEDDB — stores PCM16 chunks for replay
  1273→   =================================================== */
  1274→
  1275→function createDBStores(event) {
  1276→    const d = event.target.result;
  1277→    if (!d.objectStoreNames.contains('sessions')) {
  1278→        const s = d.createObjectStore('sessions', { keyPath: 'id', autoIncrement: true });
  1279→        s.createIndex('status',    'status',    { unique: false });
  1280→        s.createIndex('createdAt', 'createdAt', { unique: false });
  1281→    }
  1282→    if (!d.objectStoreNames.contains('chunks')) {
  1283→        const c = d.createObjectStore('chunks', { keyPath: 'id', autoIncrement: true });
  1284→        c.createIndex('sessionId', 'sessionId', { unique: false });
  1285→        c.createIndex('seq',       'seq',       { unique: false });
  1286→    }
  1287→}
  1288→
  1289→async function initIndexedDB() {
  1290→    return new Promise((resolve) => {
  1291→        const request = indexedDB.open('brainwave-replay', 1);
  1292→
  1293→        request.onerror = () => {
  1294→            console.warn('IndexedDB not available, replay disabled');
  1295→            storageAvailable = false;
  1296→            resolve(false);
  1297→        };
  1298→
  1299→        request.onsuccess = () => {
  1300→            db = request.result;
  1301→            if (!db.objectStoreNames.contains('sessions') || !db.objectStoreNames.contains('chunks')) {
  1302→                db.close();
  1303→                const del = indexedDB.deleteDatabase('brainwave-replay');
  1304→                del.onsuccess = () => {
  1305→                    const reopen = indexedDB.open('brainwave-replay', 1);
  1306→                    reopen.onsuccess       = () => { db = reopen.result; storageAvailable = true; updateReplayButtonState(); resolve(true); };
  1307→                    reopen.onerror         = () => { storageAvailable = false; resolve(false); };
  1308→                    reopen.onupgradeneeded = createDBStores;
  1309→                };
  1310→                del.onerror = () => { storageAvailable = false; resolve(false); };
  1311→                return;
  1312→            }
  1313→            storageAvailable = true;
  1314→            updateReplayButtonState();
  1315→            resolve(true);
  1316→        };
  1317→
  1318→        request.onupgradeneeded = createDBStores;
  1319→    });
  1320→}
  1321→
  1322→async function createSession() {
  1323→    if (!db) return null;
  1324→    return new Promise((resolve, reject) => {
  1325→        const tx    = db.transaction(['sessions'], 'readwrite');
  1326→        const store = tx.objectStore('sessions');
  1327→        const req   = store.add({ createdAt: new Date(), status: 'recording', sampleRate: 24000, channelCount: 1, durationMs: 0 });
  1328→        req.onsuccess = () => {
  1329→            currentSessionId  = req.result;
  1330→            sessionStartTime  = performance.now();
  1331→            chunkSeq          = 0;
  1332→            appendChunk(currentSessionId, { seq: 0, deltaMs: 0, kind: 'start', payload: null, byteLength: 0 });
  1333→            resolve(currentSessionId);
  1334→        };
  1335→        req.onerror = () => reject(req.error);
  1336→    });
  1337→}
  1338→
  1339→async function appendChunk(sessionId, chunk) {
  1340→    if (!db || !sessionId) return;
  1341→    return new Promise((resolve) => {
  1342→        const tx    = db.transaction(['chunks'], 'readwrite');
  1343→        const store = tx.objectStore('chunks');
  1344→        const req   = store.add({ sessionId, seq: chunk.seq, deltaMs: chunk.deltaMs, kind: chunk.kind, payload: chunk.payload, byteLength: chunk.byteLength });
  1345→        req.onsuccess = () => resolve();
  1346→        req.onerror   = () => resolve(); // don't fail recording on storage error
  1347→    });
  1348→}
  1349→
  1350→async function completeSession(sessionId, durationMs) {
  1351→    if (!db || !sessionId) return;
  1352→    return new Promise((resolve) => {
  1353→        const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1354→        const sessionsStore = tx.objectStore('sessions');
  1355→        const chunksStore   = tx.objectStore('chunks');
  1356→        const req           = sessionsStore.get(sessionId);
  1357→        req.onsuccess = () => {
  1358→            const sess = req.result;
  1359→            sess.status    = 'completed';
  1360→            sess.durationMs = durationMs;
  1361→            sessionsStore.put(sess);
  1362→            chunksStore.add({ sessionId, seq: chunkSeq++, deltaMs: durationMs, kind: 'stop', payload: null, byteLength: 0 });
  1363→            enforceQuota({ maxSessions: 5 });
  1364→            resolve();
  1365→        };
  1366→        req.onerror = () => resolve();
  1367→    });
  1368→}
  1369→
  1370→async function enforceQuota({ maxSessions }) {
  1371→    if (!db) return;
  1372→    const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1373→    const sessionsStore = tx.objectStore('sessions');
  1374→    const sessions      = [];
  1375→    sessionsStore.index('createdAt').openCursor().onsuccess = (event) => {
  1376→        const cursor = event.target.result;
  1377→        if (cursor) { sessions.push(cursor.value); cursor.continue(); }
  1378→        else {
  1379→            sessions.sort((a, b) => a.createdAt - b.createdAt);
  1380→            while (sessions.length > maxSessions) deleteSession(sessions.shift().id);
  1381→        }
  1382→    };
  1383→}
  1384→
  1385→async function deleteSession(sessionId) {
  1386→    if (!db) return;
  1387→    const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1388→    const sessionsStore = tx.objectStore('sessions');
  1389→    const chunksStore   = tx.objectStore('chunks');
  1390→    chunksStore.index('sessionId').openKeyCursor(IDBKeyRange.only(sessionId)).onsuccess = (event) => {
  1391→        const cursor = event.target.result;
  1392→        if (cursor) { chunksStore.delete(cursor.primaryKey); cursor.continue(); }
  1393→    };
  1394→    sessionsStore.delete(sessionId);
  1395→}
  1396→
  1397→async function getLatestCompletedSession() {
  1398→    if (!db) return null;
  1399→    return new Promise((resolve) => {
  1400→        const tx    = db.transaction(['sessions'], 'readonly');
  1401→        const req   = tx.objectStore('sessions').index('status').getAll('completed');
  1402→        req.onsuccess = () => {
  1403→            const sessions = req.result;
  1404→            if (!sessions.length) { resolve(null); return; }
  1405→            sessions.sort((a, b) => b.createdAt - a.createdAt);
  1406→            resolve(sessions[0]);
  1407→        };
  1408→        req.onerror = () => resolve(null);
  1409→    });
  1410→}
  1411→
  1412→async function getSessionChunks(sessionId) {
  1413→    if (!db || !sessionId) return [];
  1414→    return new Promise((resolve) => {
  1415→        const tx  = db.transaction(['chunks'], 'readonly');
  1416→        const req = tx.objectStore('chunks').index('sessionId').getAll(sessionId);
  1417→        req.onsuccess = () => {
  1418→            const chunks = req.result;
  1419→            chunks.sort((a, b) => a.seq - b.seq);
  1420→            resolve(chunks);
  1421→        };
  1422→        req.onerror = () => resolve([]);
  1423→    });
  1424→}
  1425→
  1426→/* ===== KEYBOARD SHORTCUT ===== */
  1427→document.addEventListener('keydown', (event) => {
  1428→    if (event.code === 'Space') {
  1429→        const el = document.activeElement;
  1430→        if (!el.tagName.match(/INPUT|TEXTAREA|SELECT/) && !el.isContentEditable) {
  1431→            event.preventDefault();
  1432→            if (isListening) {
  1433→                stopQuickMode();
  1434→            } else if (isBrainstormRecording) {
  1435→                stopBrainstormRecording();
  1436→            } else if (!isBrainstormProcessing && !isReplaying) {
  1437→                startQuickMode();
  1438→            }
  1439→        }
  1440→    }
  1441→});
  1442→
  1443→/* ===== INIT ===== */
  1444→document.addEventListener('DOMContentLoaded', async () => {
  1445→    await initIndexedDB();
  1446→
  1447→    if (!SpeechRecognition) {
  1448→        notSupported.hidden = false;
  1449→        quickBtn.disabled   = true;
  1450→        quickBtn.title      = 'Speech recognition not supported in this browser';
  1451→    } else {
  1452→        initRecognition();
  1453→        initWakeRecognition();
  1454→
  1455→        // Restore hands-free setting
  1456→        handsFreeEnabled = localStorage.getItem('handsFreeEnabled') === '1';
  1457→        if (handsFreeEnabled) {
  1458→            startWakeWordListening();
  1459→        }
  1460→    }
  1461→
  1462→    // Restore brainstorm model selection
  1463→    if (modelSelect) {
  1464→        modelSelect.value = localStorage.getItem('brainstormModel') || 'gpt-realtime-mini-2025-12-15';
  1465→    }
  1466→
  1467→    initializeWebSocket();
  1468→});
