   833→  50%       { opacity: 0.5; transform: scale(0.8); }
   834→}
   835→
   836→/* ===== Hands-free toggle in settings ===== */
   837→.toggle-label {
   838→  display: flex;
   839→  align-items: center;
   840→  justify-content: space-between;
   841→  font-size: 0.85rem;
   842→  color: var(--text-muted);
   843→  font-weight: 500;
   844→  margin-top: 4px;
   845→  cursor: pointer;
   846→  user-select: none;
   847→}
   848→
   849→.toggle-switch {
   850→  position: relative;
   851→  flex-shrink: 0;
   852→}
   853→
   854→.toggle-switch input[type="checkbox"] {
   855→  /* visually hidden but accessible */
   856→  position: absolute;
   857→  opacity: 0;
   858→  width: 0;
   859→  height: 0;
   860→}
   861→
   862→.toggle-track {
   863→  display: block;
   864→  width: 44px;
   865→  height: 26px;
   866→  background: var(--surface);
   867→  border: 1px solid var(--border);
   868→  border-radius: 13px;
   869→  position: relative;
   870→  transition: background var(--transition), border-color var(--transition);
   871→  cursor: pointer;
   872→}
   873→
   874→.toggle-track::after {
   875→  content: '';
   876→  position: absolute;
   877→  top: 3px;
   878→  left: 3px;
   879→  width: 18px;
   880→  height: 18px;
   881→  border-radius: 50%;
   882→  background: var(--text-muted);
   883→  transition: transform var(--transition), background var(--transition);
   884→}
   885→
   886→.toggle-switch input:checked + .toggle-track {
   887→  background: rgba(52, 199, 89, 0.25);
   888→  border-color: #34c759;
   889→}
   890→
   891→.toggle-switch input:checked + .toggle-track::after {
   892→  transform: translateX(18px);
   893→  background: #34c759;
   894→}
   895→
   896→.toggle-switch input:focus-visible + .toggle-track {
   897→  outline: 2px solid var(--accent);
   898→  outline-offset: 2px;
   899→}
