   955→  border-color: rgba(163, 121, 221, 0.5);
   956→}
   957→
   958→.btn-process:disabled {
   959→  opacity: 0.45;
   960→  cursor: not-allowed;
   961→}
   962→
   963→.postprocess-result {
   964→  margin-top: 12px;
   965→  background: var(--surface);
   966→  border: 1px solid var(--border);
   967→  border-radius: var(--radius-sm);
   968→  padding: 12px 14px;
   969→  animation: fade-in 0.2s ease;
   970→}
   971→
   972→.postprocess-result-header {
   973→  margin-bottom: 6px;
   974→}
   975→
   976→.postprocess-label {
   977→  font-size: 0.72rem;
   978→  font-weight: 700;
   979→  text-transform: uppercase;
   980→  letter-spacing: 0.08em;
   981→  color: var(--text-muted);
   982→}
   983→
   984→.postprocess-text {
   985→  font-size: 0.92rem;
   986→  line-height: 1.6;
   987→  color: var(--text);
   988→  white-space: pre-wrap;
   989→  word-break: break-word;
   990→  min-height: 1.4em;
   991→}
   992→
   993→.postprocess-result-actions {
   994→  display: flex;
   995→  justify-content: flex-end;
   996→  margin-top: 10px;
   997→  padding-top: 10px;
   998→  border-top: 1px solid var(--border);
   999→}
  1000→
  1001→/* ===== Card Stack View ===== */
  1002→.card-stack-view {
  1003→  position: fixed;
  1004→  inset: 0;
  1005→  background: var(--bg);
  1006→  display: flex;
  1007→  flex-direction: column;
  1008→  z-index: 90;
  1009→  transform: translateX(100%);
  1010→  transition: transform 0.3s ease-out;
  1011→}
  1012→
  1013→.card-stack-view[hidden] {
  1014→  display: none;
  1015→}
  1016→
  1017→.card-stack-view.cs-visible {
  1018→  transform: translateX(0);
  1019→}
  1020→
  1021→/* Safe area insets for notched phones */
  1022→@supports (padding: env(safe-area-inset-bottom)) {
  1023→  .card-stack-view {
  1024→    padding-top: env(safe-area-inset-top);
  1025→    padding-bottom: env(safe-area-inset-bottom);
  1026→  }
  1027→}
  1028→
  1029→/* Header bar */
  1030→.cs-header {
  1031→  display: flex;
  1032→  align-items: center;
  1033→  gap: 12px;
  1034→  padding: 16px 20px 12px;
  1035→  flex-shrink: 0;
  1036→  border-bottom: 1px solid var(--border);
  1037→}
  1038→
  1039→@supports (padding: env(safe-area-inset-top)) {
  1040→  .cs-header {
  1041→    padding-top: calc(16px + env(safe-area-inset-top));
  1042→  }
  1043→}
  1044→
  1045→.cs-back-btn {
  1046→  display: flex;
  1047→  align-items: center;
  1048→  gap: 4px;
  1049→  background: transparent;
  1050→  border: none;
  1051→  color: var(--accent);
  1052→  font-size: 0.95rem;
  1053→  font-weight: 600;
  1054→  font-family: inherit;
  1055→  cursor: pointer;
  1056→  padding: 6px 0;
  1057→  min-height: 44px;
  1058→  transition: opacity var(--transition);
  1059→  flex-shrink: 0;
  1060→}
  1061→
