  1063→
  1064→.cs-back-btn svg {
  1065→  width: 20px;
  1066→  height: 20px;
  1067→}
  1068→
  1069→.cs-title {
  1070→  font-size: 1.1rem;
  1071→  font-weight: 700;
  1072→  color: var(--text);
  1073→}
  1074→
  1075→/* Scrollable card list */
  1076→.cs-cards {
  1077→  flex: 1;
  1078→  overflow-y: auto;
  1079→  padding: 16px 16px 32px;
  1080→  display: flex;
  1081→  flex-direction: column;
  1082→  gap: 10px;
  1083→  -webkit-overflow-scrolling: touch;
