  1090→.cs-cards::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }
  1091→
  1092→/* Individual card */
  1093→.cs-card {
  1094→  background: var(--bg-2);
  1095→  border: 1px solid var(--border);
  1096→  border-radius: var(--radius);
  1097→  border-left: 4px solid var(--cs-card-color, var(--border));
  1098→  overflow: hidden;
  1099→}
  1100→
  1101→/* Card type colour tokens */
  1102→.cs-card[data-type="transcript"] { --cs-card-color: rgba(163, 121, 221, 0.85); }
  1103→.cs-card[data-type="readability"] { --cs-card-color: #00b4d8; }
  1104→.cs-card[data-type="inspire"]     { --cs-card-color: var(--accent); }
  1105→
  1106→/* Card header — always visible, clickable */
  1107→.cs-card-header {
  1108→  display: flex;
  1109→  align-items: center;
  1110→  gap: 10px;
  1111→  padding: 14px 16px;
  1112→  cursor: pointer;
  1113→  user-select: none;
  1114→  -webkit-user-select: none;
  1115→  touch-action: manipulation;
  1116→  min-height: 56px;
  1117→}
  1118→
  1119→.cs-card-header:focus-visible {
  1120→  outline: 2px solid var(--accent);
  1121→  outline-offset: -2px;
  1122→}
  1123→
  1124→.cs-card-label {
  1125→  font-size: 0.72rem;
  1126→  font-weight: 700;
  1127→  text-transform: uppercase;
  1128→  letter-spacing: 0.08em;
  1129→  color: var(--cs-card-color, var(--text-muted));
  1130→  flex-shrink: 0;
  1131→}
  1132→
  1133→.cs-card-preview {
  1134→  flex: 1;
  1135→  font-size: 0.88rem;
  1136→  color: var(--text-muted);
  1137→  overflow: hidden;
  1138→  text-overflow: ellipsis;
  1139→  white-space: nowrap;
  1140→}
  1141→
  1142→.cs-card-chevron {
  1143→  flex-shrink: 0;
  1144→  color: var(--text-muted);
  1145→  transition: transform 0.3s ease-out;
  1146→}
  1147→
  1148→.cs-card-chevron svg {
  1149→  width: 16px;
  1150→  height: 16px;
  1151→  display: block;
  1152→}
  1153→
  1154→.cs-card.cs-expanded .cs-card-chevron {
  1155→  transform: rotate(180deg);
  1156→}
  1157→
  1158→/* Collapsed card body is hidden via max-height */
  1159→.cs-card-body {
  1160→  max-height: 0;
  1161→  overflow: hidden;
  1162→  transition: max-height 0.3s ease-out;
  1163→}
  1164→
  1165→.cs-card.cs-expanded .cs-card-body {
  1166→  max-height: 600px; /* large enough for typical transcripts */
  1167→}
  1168→
  1169→.cs-card-body-inner {
  1170→  padding: 0 16px 16px;
  1171→  border-top: 1px solid var(--border);
  1172→}
  1173→
  1174→/* Metadata row */
  1175→.cs-card-meta {
  1176→  display: flex;
  1177→  gap: 10px;
  1178→  font-size: 0.75rem;
  1179→  color: var(--text-muted);
  1180→  padding: 10px 0 8px;
  1181→  font-family: 'SF Mono', 'Fira Code', ui-monospace, monospace;
  1182→  letter-spacing: 0.02em;
  1183→}
  1184→
  1185→/* Transcript content with scroll */
  1186→.cs-card-text {
  1187→  font-size: 0.92rem;
  1188→  line-height: 1.6;
  1189→  color: var(--text);
  1190→  white-space: pre-wrap;
  1191→  word-break: break-word;
  1192→  max-height: 320px;
  1193→  overflow-y: auto;
  1194→  -webkit-overflow-scrolling: touch;
  1195→  scrollbar-width: thin;
  1196→  scrollbar-color: var(--border) transparent;
  1197→  padding-right: 4px;
  1198→}
  1199→
  1200→.cs-card-text::-webkit-scrollbar       { width: 3px; }
  1201→.cs-card-text::-webkit-scrollbar-track { background: transparent; }
  1202→.cs-card-text::-webkit-scrollbar-thumb { background: var(--border); border-radius: 2px; }
  1203→
  1204→/* Action buttons row */
  1205→.cs-card-actions {
  1206→  display: flex;
  1207→  gap: 8px;
  1208→  margin-top: 14px;
  1209→  flex-wrap: wrap;
  1210→}
  1211→
  1212→.cs-action-btn {
  1213→  flex: 1;
  1214→  min-width: 72px;
  1215→  min-height: 40px;
  1216→  border: 1px solid var(--border);
  1217→  border-radius: var(--radius-sm);
  1218→  background: var(--surface);
  1219→  color: var(--text-muted);
  1220→  font-size: 0.82rem;
  1221→  font-weight: 600;
  1222→  font-family: inherit;
  1223→  cursor: pointer;
  1224→  transition: background var(--transition), color var(--transition),
  1225→              border-color var(--transition);
  1226→  letter-spacing: 0.02em;
  1227→}
  1228→
  1229→.cs-action-btn:hover:not(:disabled) {
  1230→  background: var(--surface-hover);
