        case 'connecting':
            connectionStatus.classList.add('connecting');
            connectionStatus.title = 'Connecting…';
            break;
        case 'idle':
            connectionStatus.classList.add('idle');
            connectionStatus.title = 'Ready';
            break;
        default:
            connectionStatus.title = 'Disconnected';
    }
}

