    csCards.innerHTML = '';

    const wordCount = text.trim().split(/\s+/).filter(Boolean).length;
    const durationStr = durationMs > 0 ? formatDuration(durationMs) : null;
    const meta = [
        durationStr ? `${durationStr}` : null,
        `${wordCount} word${wordCount !== 1 ? 's' : ''}`,
    ].filter(Boolean);

